def max_sum(arr):
    n = len(arr)
    if n == 0:
        return 0

    # Create arrays to store the maximum sum of increasing subsequence
    # and maximum sum of decreasing subsequence
    inc = [0] * n
    dec = [0] * n

    # Initialize the inc array
    for i in range(n):
        inc[i] = arr[i]
        for j in range(i):
            if arr[i] > arr[j]:
                inc[i] = max(inc[i], inc[j] + arr[i])

    # Initialize the dec array
    for i in range(n - 1, -1, -1):
        dec[i] = arr[i]
        for j in range(i + 1, n):
            if arr[i] > arr[j]:
                dec[i] = max(dec[i], dec[j] + arr[i])

    # Find the maximum sum of bitonic subsequence
    max_sum_bitonic = 0
    for i in range(n):
        max_sum_bitonic = max(max_sum_bitonic, inc[i] + dec[i] - arr[i])

    return max_sum_bitonic
```

