def max_product(arr):
    n = len(arr)
    if n == 0:
        return 0

    max_prod = [0] * n
    max_prod[0] = arr[0]

    for i in range(1, n):
        max_prod[i] = arr[i]
        for j in range(i):
            if arr[i] > arr[j]:
                max_prod[i] = max(max_prod[i], max_prod[j] * arr[i])

    return max(max_prod)
```

